const CRM_PROJECTS=[
  {id:'WO-1042',name:'Island Sound Collective',company:'Island Sound Collective',date:'2026-11-14',event:'EDM / dance event',stage:'lead',status:'Tour scheduled',score:86,budget:'$25k–$50k',attendance:320,tour:'Scheduled · Oct 2',proposal:'Not started',contract:'Not started',deposit:'Not due',complexity:'High',next:'Production site tour',tasks:['Confirm box-truck access questions','Prepare tour map','Request preliminary rider'],timeline:['Inquiry received','Qualification complete','Tour scheduled']},
  {id:'WO-1038',name:'Pacific Production Co.',company:'Pacific Production Co.',date:'2027-02-20',event:'Concert / live music',stage:'proposal',status:'Proposal sent',score:78,budget:'$10k–$25k',attendance:250,tour:'Completed',proposal:'Sent · revision 1',contract:'Pending proposal acceptance',deposit:'Not due',complexity:'Moderate',next:'Proposal follow-up',tasks:['Follow up on proposal','Confirm generator vendor','Review security estimate'],timeline:['Inquiry received','Qualified','Tour completed','Proposal sent']},
  {id:'WO-1029',name:'Summit Retreat Group',company:'Summit Retreat Group',date:'2027-04-09',event:'Retreat / immersive gathering',stage:'booked',status:'Production planning',score:91,budget:'$50k+',attendance:180,tour:'Completed',proposal:'Accepted',contract:'Executed',deposit:'Paid',complexity:'Moderate',next:'T-90 production kickoff',tasks:['Schedule production kickoff','Collect vendor roster','Draft multi-day site plan'],timeline:['Inquiry received','Qualified','Tour completed','Proposal accepted','Contract executed','Deposit paid','Production planning']}
];
const list=document.querySelector('[data-crm-projects]');
if(list){
  let selected=CRM_PROJECTS[0].id;
  const search=document.querySelector('[data-crm-search]'); const stage=document.querySelector('[data-crm-stage]'); const score=document.querySelector('[data-crm-score]'); const count=document.querySelector('[data-crm-count]'); const detail=document.querySelector('[data-crm-detail]');
  const bucket=(n)=>n>=80?'priority':n>=60?'qualified':n>=40?'review':'nurture';
  const renderDetail=()=>{ const p=CRM_PROJECTS.find(x=>x.id===selected)||CRM_PROJECTS[0]; detail.innerHTML=`<div class="crm-detail-head"><div><span class="crm-stage">${p.stage}</span><h2>${p.name}</h2><p>${p.event} · ${p.date} · ${p.attendance} guests</p></div><div class="score-ring"><strong>${p.score}</strong><span>/100</span></div></div><div class="crm-status-grid"><div><span>Project status</span><strong>${p.status}</strong></div><div><span>Complexity</span><strong>${p.complexity}</strong></div><div><span>Site tour</span><strong>${p.tour}</strong></div><div><span>Proposal</span><strong>${p.proposal}</strong></div><div><span>Contract</span><strong>${p.contract}</strong></div><div><span>Deposit</span><strong>${p.deposit}</strong></div></div><div class="crm-subgrid"><section><p class="eyebrow">Next actions</p><h3>${p.next}</h3><ul>${p.tasks.map(t=>`<li>${t}</li>`).join('')}</ul></section><section><p class="eyebrow">Event-production timeline</p><div class="mini-timeline">${p.timeline.map((t,i)=>`<div class="done"><span>${i+1}</span><b>${t}</b></div>`).join('')}<div><span>${p.timeline.length+1}</span><b>${p.next}</b></div></div></section></div><div class="crm-field-preview"><p class="eyebrow">Commercial + qualification snapshot</p><div><span>Budget</span><b>${p.budget}</b><span>Qualification</span><b>${bucket(p.score)}</b><span>Owner</span><b>Wild Ones team</b><span>Brand</span><b>Wild Ones</b></div></div>`; };
  const render=()=>{ const q=(search.value||'').toLowerCase(); const rows=CRM_PROJECTS.filter(p=>(stage.value==='all'||p.stage===stage.value)&&(score.value==='all'||bucket(p.score)===score.value)&&(!q||`${p.name} ${p.company} ${p.date} ${p.event}`.toLowerCase().includes(q))); count.textContent=`${rows.length} shown`; list.innerHTML=rows.map(p=>`<button class="crm-project ${p.id===selected?'selected':''}" data-id="${p.id}"><div><span>${p.stage} · ${p.status}</span><strong>${p.name}</strong><small>${p.event} · ${p.date}</small></div><b>${p.score}</b></button>`).join('')||'<p class="muted-copy">No projects match these filters.</p>'; list.querySelectorAll('[data-id]').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.id;render();renderDetail();})); renderDetail(); };
  [search,stage,score].forEach(el=>el.addEventListener(el===search?'input':'change',render)); render();
}